    public function getSourceContext(): Source
    {
        return new Source("{% extends 'base.html.twig' %}

{% block title %}ExamenAlumno index{% endblock %}

{% block body %}
    <h1>Listado de Exámenes de Alumnos</h1>

    <table class=\"table\">
        <thead>
            <tr>
                <th>ID</th>
                <th>Nota</th>
                <th>Tomo</th>
                <th>Folio</th>
                <th>Acciones</th>
            </tr>
        </thead>
        <tbody>
        {% for examen_alumno in examen_alumnos %}
            <tr>
                <td>{{ examen_alumno.id }}</td>
                <td>{{ examen_alumno.nota }}</td>
                <td>{{ examen_alumno.tomo }}</td>
                <td>{{ examen_alumno.folio }}</td>
                <td>
                    <a href=\"{{ path('app_examen_alumno_show', {'id': examen_alumno.id}) }}\">Mostrar</a>
                    <a href=\"{{ path('app_examen_alumno_edit', {'id': examen_alumno.id}) }}\">Editar</a>
                </td>
            </tr>
        {% else %}
            <tr>
                <td colspan=\"5\">No se encontraron registros</td>
            </tr>
        {% endfor %}
        </tbody>
    </table>

    <a href=\"{{ path('app_examen_alumno_new') }}\">Crear Nuevo Examen de Alumno</a>
{% endblock %}
", "examen_alumno/index.html.twig", "C:\\xampp\\htdocs\\local\\templates\\examen_alumno\\index.html.twig");
